import{_ as a,o as n,c as i,aj as e}from"./chunks/framework.BdtAaXf2.js";const k=JSON.parse('{"title":"HarmonyOS 评论回复弹窗最佳实践","description":"","frontmatter":{},"headers":[],"relativePath":"HarmonyOS 最佳实践/12-评论回复弹窗/12-评论回复弹窗.md","filePath":"HarmonyOS 最佳实践/12-评论回复弹窗/12-评论回复弹窗.md","lastUpdated":1750695195000,"__rawMarkdown":"# HarmonyOS 评论回复弹窗最佳实践\\n\\n## 前言\\n\\n在移动应用开发中，评论回复功能是一个常见且重要的交互场景。本文将详细介绍如何在 HarmonyOS 中实现一个功能完善的评论回复弹窗，包括弹窗选型、富文本编辑、软键盘适配等关键技术点。\\n\\n## 功能概述\\n\\n我们要实现的评论回复弹窗具备以下功能：\\n- 支持文字输入\\n- 支持表情选择\\n- 支持@好友功能\\n- 软键盘与表情面板无缝切换\\n- 良好的用户体验\\n\\n## 技术选型分析\\n\\n### 弹窗组件选型\\n\\n在开始开发之前，我们需要选择合适的弹窗实现方案。HarmonyOS 提供了多种弹窗实现方式，我们对比了三种主要方案：\\n\\n通过对[CustomDialog自定义弹窗](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-methods-custom-dialog-box)、[bindSheet半模态弹窗](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-universal-attributes-sheet-transition#bindsheet)、[Navigation Dialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-navigation-navigation#%E9%A1%B5%E9%9D%A2%E6%98%BE%E7%A4%BA%E7%B1%BB%E5%9E%8B)三种弹窗方案进行尝试，发现自定义弹窗和半模态弹窗有一定规格限制，会产生一些无法避免的问题，最终选用[Navigation Dialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-navigation-navigation#%E9%A1%B5%E9%9D%A2%E6%98%BE%E7%A4%BA%E7%B1%BB%E5%9E%8B)方案实现评论模块弹窗。以下对三种方案优劣势进行一个详细的说明。\\n\\n#### 方案一：CustomDialog 自定义弹窗\\n\\n[CustomDialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-methods-custom-dialog-box) 是 HarmonyOS 提供的标准弹窗组件。\\n\\n**优势：**\\n- ✅ 开箱即用，无需实现弹窗交互逻辑\\n- ✅ 自动避让软键盘，使用简单\\n- ✅ 系统级组件，稳定性好\\n\\n**劣势：**\\n- ❌ 软键盘避让行为无法自定义配置\\n- ❌ 表情面板切换时会出现短暂的布局跳动\\n- ❌ 无法获取软键盘动画信息，难以实现平滑过渡\\n\\n> **问题演示：** 当用户点击表情按钮时，软键盘收起过程中表情面板会短暂显示在错误位置，影响用户体验。\\n\\n![CustomDialog 问题演示](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113823.21128572248114659490332015929896:50001231000000:2800:520DD202B70134A32EFD837572631D8D5CD570EC988449ACB02C153105C878F8.gif)\\n\\n> **注意：** [PromptAction.openCustomDialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/js-apis-arkui-uicontext#promptaction) 与 CustomDialog 效果相同，存在同样的问题。\\n\\n#### 方案二：bindSheet 半模态弹窗\\n\\n[bindSheet](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-universal-attributes-sheet-transition#bindsheet) 是 HarmonyOS 提供的半模态弹窗组件，常用于底部弹出的交互场景。\\n\\n**优势：**\\n- ✅ 开箱即用，无需实现弹窗交互逻辑\\n- ✅ 可以解决 CustomDialog 中的软键盘顶起问题\\n- ✅ 支持手势拖拽，交互体验较好\\n\\n**劣势：**\\n- ❌ 高度自适应时内部滚动行为难以控制\\n- ❌ 即使禁用拖拽条，仍可拖动弹窗\\n- ❌ 拖动过程中可能暴露表情面板，影响视觉效果\\n\\n> **问题演示：** 当禁用拖拽条后，用户仍可以拖动弹窗，这会在拖动过程中暴露底层的表情面板区域。\\n\\n![bindSheet 问题演示](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113823.88787100697224156666358266633140:50001231000000:2800:DE9D0EB1CA70932656253517BD357AE13639560D02E047DDE00BD80B11921153.gif)\\n\\n#### 方案三：Navigation Dialog（推荐方案）\\n\\n[Navigation Dialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-navigation-navigation#%E9%A1%B5%E9%9D%A2%E6%98%BE%E7%A4%BA%E7%B1%BB%E5%9E%8B) 基于 Navigation 路由系统实现的弹窗方案。\\n\\n**优势：**\\n- ✅ 完美解决前两种方案的所有问题\\n- ✅ 基于路由栈管理，弹窗与 UI 完全解耦\\n- ✅ 可精确控制软键盘避让行为\\n- ✅ 支持复杂的弹窗层级管理\\n\\n**劣势：**\\n- ❌ 需要手动实现遮罩层和点击关闭逻辑\\n- ❌ 开发复杂度相对较高\\n\\n> **重要提醒：** Navigation Dialog 的 z 轴层级较低，如果项目中同时使用多种弹窗方案，建议统一使用 Navigation Dialog 以避免层级冲突。\\n\\n### 最终选择\\n\\n经过综合对比，我们选择 **Navigation Dialog** 作为最终方案，主要原因：\\n\\n1. **完美的软键盘控制**：可以精确控制软键盘避让行为，实现平滑的切换动画\\n2. **良好的架构设计**：基于路由的设计更符合现代应用架构理念\\n3. **可扩展性强**：便于后续功能扩展和维护\\n\\n虽然开发复杂度稍高，但带来的用户体验提升是值得的。\\n\\n### 编辑区域组件选型\\n\\n评论输入框需要支持多种内容类型：\\n- 📝 **文字输入**：普通文本内容\\n- 😊 **表情符号**：图片形式的表情\\n- 👥 **@好友功能**：特殊样式的用户标签\\n\\n#### RichEditor 组件介绍\\n\\n对于这种图文混排的需求，HarmonyOS 提供的 [RichEditor](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor) 组件是最佳选择。它支持：\\n\\n- **富文本编辑**：文字、图片、自定义组件混合编辑\\n- **灵活的内容管理**：通过不同的 Span 类型管理内容\\n- **丰富的交互事件**：输入、删除、选择等事件监听\\n\\n#### 内容类型与实现方法\\n\\nRichEditor 提供了三种主要的内容添加方法：\\n\\n| 内容类型 | 实现方法 | 用途 |\\n|---------|---------|------|\\n| 文字 | [addTextSpan](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#addtextspan) | 普通文本内容 |\\n| 图片 | [addImageSpan](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#addimagespan) | 表情图片 |\\n| 自定义组件 | [addBuilderSpan](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#addbuilderspan11) | @好友标签 |\\n\\n> **术语说明：** 为方便理解，我们将通过这三种方法添加的内容分别称为 `textSpan`、`imageSpan`、`builderSpan`。\\n\\n#### @好友功能实现方案对比\\n\\n对于 @好友功能，我们有两种实现方案可选：\\n\\n##### 方案一：使用 addTextSpan 实现\\n\\n将 @好友 作为普通文本处理。\\n\\n**问题分析：**\\n- ❌ **文本合并问题**：前后输入的文字会自动与 @好友 文本合并，破坏标签的独立性\\n- ❌ **交互复杂**：需要手动处理光标定位和整体删除逻辑\\n- ❌ **数据关联困难**：只能获取昵称文本，无法关联用户的完整信息（如 ID、头像等）\\n\\n##### 方案二：使用 addBuilderSpan 实现（推荐）\\n\\n将 @好友 作为自定义组件处理。\\n\\n**优势分析：**\\n- ✅ **独立性好**：不会与前后文字合并，保持标签完整性\\n- ✅ **交互简单**：系统自动处理光标和删除逻辑\\n- ✅ **数据丰富**：可以维护完整的用户信息，便于后续处理\\n\\n**注意事项：**\\n- 需要手动维护 builderSpan 的信息，但这也带来了更大的灵活性\\n\\n##### 最终选择\\n\\n我们选择 **addBuilderSpan** 方案，主要考虑：\\n1. **更好的用户体验**：@好友 标签作为整体，交互更自然\\n2. **更强的扩展性**：可以轻松添加头像、样式等丰富元素\\n3. **更可靠的数据管理**：完整的用户信息便于业务处理\\n\\n## 核心功能实现\\n\\n### 1. 弹窗显示实现\\n\\n#### 功能流程\\n\\n评论弹窗的显示流程如下：\\n1. 用户在视频页面点击消息按钮\\n2. 弹出评论列表页面\\n3. 用户点击写评论按钮\\n4. 弹出评论输入弹窗\\n\\n![弹窗显示流程](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113823.41492548141515634230758802114557:50001231000000:2800:EBF89F0BFC75642055069A6F1440ACE661042B11B7DFE7754C2939754FABE7CB.gif)\\n\\n#### 技术实现要点\\n\\n##### 1. Navigation 配置\\n\\n```typescript\\n// 主页面 Navigation 配置\\nNavigation() {\\n  // 页面内容\\n}\\n.mode(NavigationMode.Stack)  // 设置为栈模式\\n.hideTitleBar(true)         // 隐藏标题栏\\n```\\n\\n##### 2. 弹窗组件结构\\n\\n```typescript\\n// 弹窗页面组件\\n@Component\\nstruct CommentDialog {\\n  build() {\\n    NavDestination() {\\n      Stack() {\\n        // 遮罩层\\n        Column()\\n          .width(\'100%\')\\n          .height(\'100%\')\\n          .backgroundColor(\'rgba(0,0,0,0.5)\')\\n          .onClick(() => {\\n            // 点击遮罩关闭弹窗\\n            router.back()\\n          })\\n        \\n        // 弹窗内容\\n        Column() {\\n          // 评论输入组件\\n        }\\n        .backgroundColor(Color.White)\\n        .borderRadius(12)\\n      }\\n    }\\n    .mode(NavDestinationMode.DIALOG)  // 设置为弹窗模式\\n    .expandSafeArea([SafeAreaType.KEYBOARD])  // 不避让软键盘\\n  }\\n}\\n```\\n\\n##### 3. 关键配置说明\\n\\n| 配置项 | 作用 | 重要性 |\\n|--------|------|--------|\\n| `NavigationMode.Stack` | 启用路由栈管理 | ⭐⭐⭐ |\\n| `NavDestinationMode.DIALOG` | 设置为弹窗类型 | ⭐⭐⭐ |\\n| `expandSafeArea([SafeAreaType.KEYBOARD])` | 不避让软键盘 | ⭐⭐⭐ |\\n| 遮罩层点击事件 | 提供关闭交互 | ⭐⭐ |\\n\\n#### 弹窗管理策略\\n\\n- **弹出**：通过 `router.pushUrl()` 进入路由栈\\n- **关闭**：通过 `router.back()` 退出路由栈\\n- **层级**：路由栈的顺序决定弹窗层级关系\\n\\n### 2. 软键盘和表情面板切换适配\\n\\n#### 功能需求\\n\\n在评论弹窗中，用户需要能够在软键盘和表情面板之间无缝切换，提供良好的输入体验。\\n\\n![软键盘表情切换](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113823.89308693689825239388198025312122:50001231000000:2800:DB5CF03B542AEE021C84DCCBB26F1BC5723925B8A5B57C2E42202527F9C7B98A.gif)\\n\\n#### 技术实现方案\\n\\n##### 1. 自定义键盘控制\\n\\n本文选择自定义键盘来控制软键盘和表情面板的切换：\\n\\n- **显示表情面板**：设置 [RichEditor.customKeyboard](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#customkeyboard) 为表情面板组件的构建函数 `EmojiKeyboard`\\n- **显示软键盘**：设置 `customKeyboard` 属性为 `undefined`\\n- **焦点管理**：通过这种方式切换时无需手动处理 RichEditor 焦点\\n\\n##### 2. 高度适配策略\\n\\n为保证切换过程中评论模块整体高度不变，需要实现以下逻辑：\\n\\n**软键盘高度监听：**\\n```typescript\\n// 监听软键盘高度变化\\nwindow.on(\'keyboardHeightChange\', (height: number) => {\\n  if (height > 0) {\\n    this.keyboardHeight = height;\\n  }\\n});\\n```\\n\\n**高度计算规则：**\\n- 表情面板高度 = 常用表情列表高度 + 软键盘高度\\n- 占位元素高度 = 当前显示组件的高度（软键盘或表情面板）\\n\\n##### 3. 布局适配实现\\n\\n由于弹窗设置了不避让软键盘，需要通过占位元素来控制布局：\\n\\n```typescript\\n// 占位元素高度控制\\n@State placeholderHeight: number = 0;\\n\\n// 切换到软键盘时\\nthis.placeholderHeight = this.keyboardHeight;\\n\\n// 切换到表情面板时  \\nthis.placeholderHeight = this.emojiPanelHeight + this.keyboardHeight;\\n```\\n\\n#### 注意事项\\n\\n- ⚠️ **内存管理**：组件销毁前必须取消键盘高度监听事件\\n- ⚠️ **高度变化**：软键盘高度可能被用户手动调整，需要实时监听\\n- ⚠️ **时序控制**：切换过程中要确保高度设置的时序正确\\n\\n### 3. @好友功能实现\\n\\n#### 功能概述\\n\\n@好友功能允许用户在评论中提及其他用户，被@的用户会收到通知，这是社交应用中的重要功能。\\n\\n#### 触发方式\\n\\n用户可以通过两种方式触发@好友功能：\\n1. **点击@按钮**：直接点击编辑区域的@按钮\\n2. **键盘输入**：在软键盘上输入@符号\\n\\n  ![](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113824.25812803030167053648920547579046:50001231000000:2800:B789FEE11854FD2FD743AAD611B1179334B3545DCDA92A3661C802ECF58E5338.gif)\\n\\n#### 实现流程\\n\\n##### 1. 触发@功能\\n\\n**点击@按钮时：**\\n```typescript\\n// 添加@符号并显示好友列表\\nthis.richEditorController.addTextSpan(\'@\', {\\n  style: {\\n    fontColor: Color.Blue\\n  }\\n});\\nthis.showFriendList = true;\\n```\\n\\n**监听键盘输入：**\\n```typescript\\n// 监听输入事件，统一处理@符号\\n.aboutToIMEInput((value: RichEditorInsertValue) => {\\n  if (value.insertValue === \'@\') {\\n    // 触发@好友逻辑\\n    this.showFriendList = true;\\n    return true; // 阻止默认输入\\n  }\\n  return false;\\n})\\n```\\n\\n通过 [RichEditorController.addTextSpan](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#addtextspan) 添加@符号，并显示好友列表。同时监听 [RichEditor.aboutToIMEInput](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#abouttoimeinput) 事件，统一处理点击@按钮和键盘输入@的逻辑。\\n\\n  在好友列表中点击好友头像时，通过[RichEditorController.getSpans](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#getspans)可以获取光标前一个span的内容，若光标前一个span是内容为@的textSpan，则先删除，然后通过[RichEditorController.addBuilderSpan](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#addbuilderspan11)将“@\\\\[好友昵称\\\\]”以指定的样式作为一个整体添加到编辑区域中。\\n\\n### 4. 内容删除功能\\n\\n#### 功能需求\\n\\n在删除@好友内容时，需要实现智能删除：第一次点击删除键时选中整个@好友组件，第二次点击时整体删除，而不是逐字符删除。\\n\\n![删除功能演示](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113824.20287915377951093579309018074287:50001231000000:2800:A48EC5841269082BB512C5DF014428C6CC555CF1C28B46A31DBD61C36360A03B.gif)\\n\\n#### 实现方案\\n\\n```typescript\\n// 监听删除事件\\n.aboutToDelete((value: RichEditorDeleteValue) => {\\n  // 获取要删除的span信息\\n  const spans = this.richEditorController.getSpans(value.offset, value.offset + value.length);\\n  \\n  if (spans.length > 0) {\\n    const span = spans[0];\\n    \\n    // 如果是builderSpan（@好友）且未被选中\\n    if (span.spanType === \'builderSpan\' && !this.isSpanSelected(span)) {\\n      // 第一次删除：选中整个@好友组件\\n      this.richEditorController.setSelection(span.start, span.end);\\n      return false; // 阻止默认删除行为\\n    }\\n  }\\n  \\n  return true; // 允许默认删除行为\\n})\\n```\\n\\n#### 技术要点\\n\\n| 功能 | API | 说明 |\\n|------|-----|------|\\n| 删除监听 | `aboutToDelete()` | 监听删除操作，可阻止默认行为 |\\n| 内容选中 | `setSelection()` | 选中指定范围的内容 |\\n| 获取内容 | `getSpans()` | 获取指定位置的span信息 |\\n\\n通过 [RichEditor.aboutToDelete](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#abouttodelete) 事件监听删除操作，使用 [RichEditorController.setSelection](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#setselection11) 实现@好友组件的整体选中和删除。\\n\\n### 5. 内容获取与展示\\n\\n#### 功能概述\\n\\n当用户完成评论编辑后，需要获取编辑区域的所有内容（文字、表情、@好友），并进行统一的数据处理和展示。\\n\\n![内容展示效果](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113824.35426684108552004081985772349110:50001231000000:2800:7AE40EF9CA4BB477A35DF7FC5F15F2FDBCF0D161E0E2406524C9C2900F5C96CE.png)\\n\\n#### 数据类型映射\\n\\n通过 [RichEditorController.getSpans](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#getspans) 获取编辑区域内容，返回值包含 [RichEditorTextSpanResult](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#richeditortextspanresult) 和 [RichEditorImageSpanResult](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-richeditor#richeditorimagespanresult) 两种类型。\\n\\n不同内容类型与数据类型的对应关系：\\n\\n  textSpan可通过RichEditorTextSpanResult.value获取文字内容。imageSpan可通过RichEditorImageSpanResult.valueResourceStr获取图片资源。但是builderSpan在RichEditorImageSpanResult中获取不到任何相关的内容信息，所以在点击好友头像添加@好友内容时需要手动将这些builderSpan进行维护。\\n\\n  实际开发中编辑区域不同类型的内容往往需要一种统一的数据结构来表达，方便传输和存储。该数据结构需要不仅能对编辑区域内容进行记录，也需要有携带一些额外信息的能力，比如携带@好友相关的用户信息。本文定义为RichEditorSpan。（实际开发中需要的属性字段根据需求灵活调整）。\\n\\n  使用RichEditorSpan\\\\[\\\\]类型的数组builderSpans来维护@好友时的builderSpan，需要注意的是要保证每个builderSpan在数组中的顺序要与实际内容中出现的顺序一致。在添加builderSpan时，通过计算当前光标位置前面builderSpan的个数，来确定添加到builderSpans数组中的位置，并把需要携带的好友信息放入data属性中。\\n\\n  发送评论时，将获取到的内容用RichEditorSpan\\\\[\\\\]类型的数组richEditorSpans进行统一地表达。通过getSpans获取所有内容，如果是textSpan，通过value属性取出文字内容，设置RichEditorSpan.type为text，如果是imageSpan，通过valueResourceStr属性获取图片资源，设置RichEditorSpan.type为image。如果是builderSpan，按顺序从数组builderSpans中获取，并将他们按顺序添加到richEditorSpans中。\\n\\n  最终生成的richEditorSpans数据格式如下：\\n\\n  当需要展示评论内容时，只需要对richEditorSpans进行遍历，根据type属性，分别对文字、表情、@好友进行展示逻辑的处理。具体展示形式开发者根据实际需求确定。\\n\\n- 选择图片\\n\\n  点击图片按钮拉起系统相册，选择本地图片进行上传。该功能使用场景相对独立，本文不详细介绍。开发者需要进一步了解详情，可参考以下sample。\\n\\n  - [选择并查看文档和媒体文件](https://gitee.com/harmonyos_samples/picker)\\n  - [文件管理](https://developer.huawei.com/consumer/cn/codelabsPortal/carddetails/tutorials_NEXT-FilesManger)\\n  - [发布图片评论](https://gitee.com/harmonyos_samples/image-comment)\\n"}'),t={name:"HarmonyOS 最佳实践/12-评论回复弹窗/12-评论回复弹窗.md"};function r(l,s,p,h,o,d){return n(),i("div",null,[...s[0]||(s[0]=[e("",135)])])}const E=a(t,[["render",r]]);export{k as __pageData,E as default};
